                entity="FactoryRunUsage",
                entity_id=factory_run_usage_id,
                field="action",
                old_value=None, # For action, old/new values are less meaningful, just log the action.
                new_value=action,
                action=action
            )
            # More specific field audits would require fetching the before-image

        return JSONResponse(content=json.loads(json_result), status_code=200)
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
