    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 3, "factoryRunUsageId": id }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
